import { webkit } from 'playwright';
const browser=await webkit.launch({headless:true});
try{
  const page=await browser.newPage({userAgent:'Mozilla/5.0 (iPhone; CPU iPhone OS 18_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.6 Mobile/15E148 Safari/604.1',viewport:{width:390,height:844}});
  const errors=[];page.on('pageerror',e=>errors.push(String(e.message||e)));
  await page.goto('http://127.0.0.1:4217/shogi-v21528/index.html?iphoneLite='+Date.now(),{waitUntil:'domcontentloaded',timeout:120000});
  await page.waitForFunction(()=>document.querySelectorAll('#chars .ch').length===26,{timeout:120000});
  await page.waitForTimeout(1800);
  const base=await page.evaluate(()=>{const cards=[...document.querySelectorAll('#chars .ch')],names=cards.map(c=>(c.querySelector('.chName')?.textContent||c.querySelector('img')?.alt||'').trim()),badImages=cards.map((c,i)=>({name:names[i],img:c.querySelector('img')})).filter(x=>!x.img?.complete||x.img.naturalWidth<1).map(x=>x.name),sound=window.AI_SHOGI_PIECE_SOUND?.audit?.()||null,save=window.AI_SHOGI_GAME_SAVE||null,side=document.getElementById('sideSelect2157');return{cards:cards.length,unique:new Set(names).size,names,badImages,coi:crossOriginIsolated,sound,save:{api:!!save,version:save?.version||'',saveBtn:!!document.getElementById('saveGameBtn21530'),resumeBtn:!!document.getElementById('resumeGameBtn21530')},side:{exists:!!side,values:side?[...side.options].map(o=>o.value):[]},futureApi:!!window.AI_SHOGI_YANEURAOU_FUTURE};});
  if(base.cards!==26||base.unique!==26||base.badImages.length||!base.coi||!base.futureApi)throw Error('base '+JSON.stringify(base));
  if(base.names[25]!=='未来からやってきたみつき')throw Error('future slot '+base.names[25]);
  if(base.sound?.enabled!==true||base.sound?.buttons!==2)throw Error('sound '+JSON.stringify(base.sound));
  if(!base.save.api||!base.save.saveBtn||!base.save.resumeBtn)throw Error('save '+JSON.stringify(base.save));
  if(!base.side.exists||JSON.stringify(base.side.values)!==JSON.stringify(['sente','gote','random']))throw Error('side '+JSON.stringify(base.side));
  const ranks=[];for(const [i,want] of [[25,'強さ1位・未来最強'],[0,'強さ2位・現代最強'],[1,'強さ3位'],[2,'強さ4位'],[3,'強さ5位'],[4,'強さ6位']]){await page.locator('#chars .ch').nth(i).click();await page.waitForTimeout(100);const got=String(await page.locator('#oppRank').textContent()||'').trim();ranks.push({i,got});if(got!==want)throw Error('rank '+i+' '+got);}
  const layouts=[];for(const vp of [{width:390,height:844},{width:844,height:390}]){await page.setViewportSize(vp);await page.waitForTimeout(200);const normal=await page.evaluate(()=>{const b=document.getElementById('board')?.getBoundingClientRect();return{vw:innerWidth,vh:innerHeight,board:b&&{l:b.left,r:b.right,w:b.width,h:b.height},scrollW:document.documentElement.scrollWidth}});if(!normal.board||normal.board.w<120||normal.board.h<120||normal.board.l<-2||normal.board.r>normal.vw+2)throw Error('normal '+JSON.stringify(normal));await page.locator('#focusBtn').click();await page.waitForTimeout(160);const focus=await page.evaluate(()=>{const root=document.getElementById('focus'),b=document.getElementById('fboard')?.getBoundingClientRect(),p=document.getElementById('foppPortrait')?.getBoundingClientRect();return{display:root?getComputedStyle(root).display:'none',vw:innerWidth,board:b&&{l:b.left,r:b.right,w:b.width,h:b.height},portrait:p&&{w:p.width,h:p.height}}});if(focus.display==='none'||!focus.board||focus.board.w<120||focus.board.l<-2||focus.board.r>focus.vw+2||!focus.portrait||focus.portrait.w<20)throw Error('focus '+JSON.stringify(focus));await page.locator('#closeBtn').click();layouts.push({vp,normal,focus});}
  if(errors.length)throw Error('pageerrors '+errors.join(' | '));
  console.log('PASS_FINAL_IPHONE_LITE '+JSON.stringify({base:{cards:base.cards,unique:base.unique,badImages:base.badImages,coi:base.coi,sound:base.sound,save:base.save,side:base.side},ranks,layouts}));
}finally{await browser.close();}
